// 绘制腿（髋→膝盖→脚）
function drawLeg(hip, knee, foot, color, darkColor, opacity) {
    let html = '';
    html += `<g opacity="${opacity}">`;

    // 大腿（髋到膝盖）
    html += `<line x1="${hip.x}" y1="${hip.y}" x2="${knee.x}" y2="${knee.y}" 
                stroke="${color}" stroke-width="8" stroke-linecap="round"/>`;

    // 小腿（膝盖到脚）
    html += `<line x1="${knee.x}" y1="${knee.y}" x2="${foot.x}" y2="${foot.y}" 
                stroke="${color}" stroke-width="6" stroke-linecap="round"/>`;

    // 膝盖关节
    html += `<circle cx="${knee.x}" cy="${knee.y}" r="4" fill="${darkColor}"/>`;

    // 蹼足（在踏板位置，始终朝向前方/右方）
    // 脚的方向由小腿角度决定（从小腿末端向前延伸）
    const shinAngle = Math.atan2(foot.y - knee.y, foot.x - knee.x);
    // 蹼足方向：沿小腿方向延伸，保持向前
    const footAngle = shinAngle;
    html += drawFoot(foot, footAngle, color, darkColor, opacity);

    html += `</g>`;
    return html;
}

// 绘制蹼足（扁平宽脚，三趾有蹼，始终朝向前方）
function drawFoot(pos, angle, color, darkColor, opacity) {
    const a = angle * 180 / Math.PI;
    let html = '';
    html += `<g transform="translate(${pos.x}, ${pos.y}) rotate(${a})" opacity="${opacity}">`;
    // 蹼足形状（扁平宽脚，趾尖朝前）
    html += `<path d="M -3 -2 C 2 -4, 8 -4, 14 -1 L 18 0 L 14 0 L 12 4 L 8 1 L 4 4 L 0 1 L -3 0 Z" 
                fill="${color}" stroke="${darkColor}" stroke-width="0.5"/>`;
    // 蹼（趾间膜）
    html += `<path d="M 4 0 L 8 3 L 12 3 L 16 0" fill="none" stroke="${darkColor}" stroke-width="0.8"/>`;
    html += `</g>`;
    return html;
}
